export const messages={en,ta}

export function createTranslator(language='en'){
 const lang=messages[language]?language:'en'
 return (key,fallback)=>{
  const value=messages[lang]?.[key] ?? messages.en[key] ?? fallback ?? key
  return value
 }
}

export function navText(moduleKey,fallback,language='en'){
 return createTranslator(language)('nav.'+moduleKey,fallback)
}
